.L19106:
    .string "(capabilities actor)\n(use actor/actor)\n(use atomic/atomic)\n(defn main () (let b (atomicbuf-new 1) (let a (spawn (fn () (atomicbuf-add b 0 1))) (begin (actor-wait a) (- (atomicview-get! (atomicbuf-freeze! b) 0) 1)))))"
